import requests

url = 'https://api.example.com/users'
response = requests.get(url, timeout=5)

if response.status_code != 200:
    print('Request failed')
    exit()

users = response.json()

if not isinstance(users, list):
    print('Unexpected data format')
else:
    for user in users:
        email = user.get('email', 'N/A')
        print(email)

