import requests

def fetch_posts_by_user(user_id):
    url = f'https://jsonplaceholder.typicode.com/posts?userId={user_id}'
    response = requests.get(url)
    posts = response.json()
    result = {}
    for post in posts:
        if len(post['body']) > 50:
            result[post['id']] = post['title']
    return result

print(fetch_posts_by_user(1))

import requests

def fetch_all_data():
    endpoints = {
        'users': 'https://jsonplaceholder.typicode.com/users',
        'posts': 'https://jsonplaceholder.typicode.com/posts',
        'comments': 'https://jsonplaceholder.typicode.com/comments'
    }
    result = {}
    for key, url in endpoints.items():
        response = requests.get(url)
        response.raise_for_status()
        result[key] = response.json()
    return result

print(fetch_all_data())

import requests

def fetch_weather(city):
    url = f'https://api.openweathermap.org/data/2.5/weather?q={city}&appid=demo'
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        temp = data['main']['temp']
        return f'Temperature in {city}: {temp}K'
    except requests.exceptions.HTTPError:
        return 'City not found'
    except KeyError:
        return 'City not found'
    except requests.exceptions.RequestException:
        return 'City not found'

print(fetch_weather('London'))
